<?php
 namespace QQWorld\Framework\Code\Test\Unit; use QQWorld\Framework\App\Filesystem\DirectoryList; use QQWorld\Framework\Code\GeneratedFiles; class GeneratedFilesTest extends \PHPUnit\Framework\TestCase { private $directoryList; private $writeInterface; private $model; protected function setUp() { $this->directoryList = $this->createPartialMock(\QQWorld\Framework\App\Filesystem\DirectoryList::class, ['getPath']); $writeFactory = $this->createMock(\QQWorld\Framework\Filesystem\Directory\WriteFactory::class); $this->writeInterface = $this->getMockBuilder(\QQWorld\Framework\Filesystem\Directory\WriteInterface::class) ->setMethods(['getPath', 'delete']) ->getMockForAbstractClass(); $writeFactory->expects($this->once())->method('create')->willReturn($this->writeInterface); $this->model = new GeneratedFiles($this->directoryList, $writeFactory); } public function testCleanGeneratedFiles($getPathMap, $isDirectoryMap, $deleteMap) { $this->writeInterface ->expects($this->any()) ->method('isExist') ->with() ->willReturnMap([ [GeneratedFiles::REGENERATE_FLAG, true], ['path/to/di', false] ]); $this->directoryList->expects($this->any())->method('getPath')->willReturnMap($getPathMap); $this->writeInterface->expects($this->any())->method('getRelativePath')->willReturnMap($getPathMap); $this->writeInterface->expects($this->any())->method('isDirectory')->willReturnMap($isDirectoryMap); $this->writeInterface->expects($this->exactly(1))->method('delete')->willReturnMap($deleteMap); $this->model->cleanGeneratedFiles(); } public function cleanGeneratedFilesDataProvider() { $pathToGeneration = 'path/to/generation'; $pathToDi = 'path/to/di'; $pathToCache = 'path/to/di'; $pathToConfig = 'path/to/config'; $getPathMap = [ [DirectoryList::GENERATED_CODE, $pathToGeneration], [DirectoryList::GENERATED_METADATA, $pathToDi], [DirectoryList::CACHE, $pathToCache], [DirectoryList::CONFIG, $pathToConfig], ]; $deleteMap = [[BP . '/' . $pathToGeneration, true], [BP . '/' . $pathToDi, true], [BP . GeneratedFiles::REGENERATE_FLAG, true], ]; return [ 'runAll' => [ $getPathMap, [[BP . '/' . $pathToGeneration, true], [BP . '/' . $pathToDi, true]], $deleteMap ], 'noDIfolder' => [ $getPathMap, [[BP . '/' . $pathToGeneration, true], [BP . '/' . $pathToDi, false]], $deleteMap], 'noGenerationfolder' => [$getPathMap, [[BP . '/' . $pathToGeneration, false], [BP . '/' . $pathToDi, true]], $deleteMap], 'nofolders' => [ $getPathMap, [[BP . '/' . $pathToGeneration, false], [BP . '/' . $pathToDi, false]], $deleteMap], ]; } public function testCleanGeneratedFilesWithNoFlag() { $this->writeInterface ->expects($this->once()) ->method('isExist') ->with(GeneratedFiles::REGENERATE_FLAG) ->willReturn(false); $this->directoryList->expects($this->never())->method('getPath'); $this->writeInterface->expects($this->never())->method('getPath'); $this->writeInterface->expects($this->never())->method('delete'); $this->model->cleanGeneratedFiles(); } public function testRequestRegeneration() { $this->writeInterface->expects($this->once())->method("touch"); $this->model->requestRegeneration(); } } 